package com.devteciot.dev_erp.Controller; import com.devteciot.dev_erp.DTO.DTOFuncionario.*; import com.devteciot.dev_erp.Service.FuncionarioService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/funcionarios") @RequiredArgsConstructor public class FuncionarioController {private final FuncionarioService s; @GetMapping public List<FuncionarioGetDTO> listar(){return s.listar();}@GetMapping("/{id}") public FuncionarioGetDTO buscar(@PathVariable Long id){return s.buscar(id);}@PostMapping public ResponseEntity<FuncionarioGetDTO> criar(@Valid @RequestBody FuncionarioPostDTO d){return ResponseEntity.status(HttpStatus.CREATED).body(s.criar(d));}@PutMapping("/{id}") public FuncionarioGetDTO atualizar(@PathVariable Long id,@Valid @RequestBody FuncionarioPostDTO d){return s.atualizar(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> excluir(@PathVariable Long id){s.excluir(id);return ResponseEntity.noContent().build();}}
